+import { test } from "node:test";
+import assert from "node:assert/strict";
+import { mkdirSync, writeFileSync, readFileSync, existsSync } from "node:fs";
+import { join } from "node:path";
+import { tmpdir } from "node:os";
+import { randomUUID } from "node:crypto";
+import { S3Client } from "@aws-sdk/client-s3";
+import { loadCases, saveCases } from "./cases";
+import type { ReviewRecord } from "../schema";
+
+const makeRecord = (overrides: Partial<ReviewRecord> = {}): ReviewRecord => ({
+  runId: randomUUID(),
+  repo: "thegoodparty/ops",
+  prNumber: 42,
+  baseSha: "aaaaaa",
+  headSha: "bbbbbb",
+  trigger: "webhook",
+  agentVersion: "1.0.0",
+  model: "claude-opus-4-6",
+  startedAt: "2024-01-01T00:00:00.000Z",
+  finishedAt: "2024-01-01T00:01:00.000Z",
+  wallTimeMs: 60000,
+  costUsd: 0.05,
+  bundle: {
+    repo: "thegoodparty/ops",
+    prNumber: 42,
+    baseRef: "develop",
+    baseSha: "aaaaaa",
+    headSha: "bbbbbb",
+    author: "swain",
+    title: "Test PR",
+    body: "A test pull request",
+    diff: "diff --git a/foo.ts b/foo.ts\n",
+    changedFiles: ["foo.ts"],
+    priorFindings: [],
+  },
+  output: { status: "complete", findings: [], summary: "LGTM" },
+  verdict: "approve",
+  action: "approved",
+  gates: [],
+  findings: [],
+  ...overrides,
+});
+
+const tmpDir = () => {
+  const dir = join(tmpdir(), `cases-test-${randomUUID()}`);
+  mkdirSync(dir, { recursive: true });
+  return dir;
+};
+
+test("loadCases from dir returns valid records", async () => {
+  const dir = tmpDir();
+  const record = makeRecord();
+  writeFileSync(join(dir, `${record.runId}.json`), JSON.stringify(record));
+
+  const records = await loadCases({ from: dir });
+  assert.equal(records.length, 1);
+  assert.equal(records[0].runId, record.runId);
+});
+
+test("loadCases from dir skips invalid JSON files with a warn", async () => {
+  const dir = tmpDir();
+  writeFileSync(join(dir, "bad.json"), "not json");
+  const record = makeRecord();
+  writeFileSync(join(dir, `${record.runId}.json`), JSON.stringify(record));
+
+  const records = await loadCases({ from: dir });
+  assert.equal(records.length, 1);
+});
+
+test("loadCases from dir skips invalid schema files with a warn", async () => {
+  const dir = tmpDir();
+  writeFileSync(join(dir, "bad.json"), JSON.stringify({ notARecord: true }));
+  const record = makeRecord();
+  writeFileSync(join(dir, `${record.runId}.json`), JSON.stringify(record));
+
+  const records = await loadCases({ from: dir });
+  assert.equal(records.length, 1);
+});
+
+test("loadCases filters by repo", async () => {
+  const dir = tmpDir();
+  const r1 = makeRecord({ repo: "thegoodparty/ops" });
+  const r2 = makeRecord({ repo: "thegoodparty/gp-webapp" });
+  writeFileSync(join(dir, `${r1.runId}.json`), JSON.stringify(r1));
+  writeFileSync(join(dir, `${r2.runId}.json`), JSON.stringify(r2));
+
+  const records = await loadCases({ from: dir, repo: "thegoodparty/ops" });
+  assert.equal(records.length, 1);
+  assert.equal(records[0].repo, "thegoodparty/ops");
+});
+
+test("loadCases applies limit", async () => {
+  const dir = tmpDir();
+  for (let i = 0; i < 5; i++) {
+    const r = makeRecord();
+    writeFileSync(join(dir, `${r.runId}.json`), JSON.stringify(r));
+  }
+
+  const records = await loadCases({ from: dir, limit: 3 });
+  assert.equal(records.length, 3);
+});
+
+test("loadCases filters onlyComplete", async () => {
+  const dir = tmpDir();
+  const complete = makeRecord({ output: { status: "complete", findings: [], summary: "ok" } });
+  const failed = makeRecord({ output: { status: "failed", reason: "agent failed" }, verdict: "failed", action: "failed" });
+  writeFileSync(join(dir, `${complete.runId}.json`), JSON.stringify(complete));
+  writeFileSync(join(dir, `${failed.runId}.json`), JSON.stringify(failed));
+
+  const records = await loadCases({ from: dir, onlyComplete: true });
+  assert.equal(records.length, 1);
+  assert.equal(records[0].runId, complete.runId);
+});
+
+test("loadCases from dir ignores non-json files", async () => {
+  const dir = tmpDir();
+  writeFileSync(join(dir, "README.md"), "# not a record");
+  const record = makeRecord();
+  writeFileSync(join(dir, `${record.runId}.json`), JSON.stringify(record));
+
+  const records = await loadCases({ from: dir });
+  assert.equal(records.length, 1);
+});
+
+test("saveCases writes records as <runId>.json files", () => {
+  const dir = tmpDir();
+  const records = [makeRecord(), makeRecord()];
+
+  saveCases(records, dir);
+
+  for (const record of records) {
+    const path = join(dir, `${record.runId}.json`);
+    assert.ok(existsSync(path), `expected ${path} to exist`);
+    const parsed = JSON.parse(readFileSync(path, "utf-8")) as ReviewRecord;
+    assert.equal(parsed.runId, record.runId);
+  }
+});
+
+test("saveCases creates the output dir if it does not exist", () => {
+  const dir = join(tmpdir(), `cases-save-test-${randomUUID()}`, "nested", "dir");
+  const record = makeRecord();
+
+  saveCases([record], dir);
+
+  assert.ok(existsSync(join(dir, `${record.runId}.json`)));
+});
+
+test("loadCases from S3 loads records and skips lock keys", async () => {
+  const record = makeRecord();
+  const calls: string[] = [];
+
+  const fakeClient = {
+    send: async (cmd: { constructor: { name: string }; input: Record<string, unknown> }) => {
+      const name = cmd.constructor.name;
+      calls.push(name);
+      if (name === "ListObjectsV2Command") {
+        return {
+          Contents: [
+            { Key: `reviews/thegoodparty/ops/42/bbbbbb/${record.runId}.json` },
+            { Key: `reviews/thegoodparty/ops/42/bbbbbb/lock` },
+          ],
+          NextContinuationToken: undefined,
+        };
+      }
+      if (name === "GetObjectCommand") {
+        const body = Buffer.from(JSON.stringify(record));
+        return {
+          Body: (async function* () { yield body; })(),
+        };
+      }
+      return {};
+    },
+  } as unknown as S3Client;
+
+  const records = await loadCases({ from: "s3" }, fakeClient);
+  assert.equal(records.length, 1);
+  assert.equal(records[0].runId, record.runId);
+  assert.ok(calls.includes("ListObjectsV2Command"));
+  assert.ok(calls.includes("GetObjectCommand"));
+});
+
+test("loadCases from S3 skips invalid records with a warn", async () => {
+  const fakeClient = {
+    send: async (cmd: { constructor: { name: string }; input: Record<string, unknown> }) => {
+      if (cmd.constructor.name === "ListObjectsV2Command") {
+        return {
+          Contents: [{ Key: "reviews/repo/1/sha/runid.json" }],
+          NextContinuationToken: undefined,
+        };
+      }
+      const body = Buffer.from(JSON.stringify({ bad: "data" }));
+      return { Body: (async function* () { yield body; })() };
+    },
+  } as unknown as S3Client;
+
+  const records = await loadCases({ from: "s3" }, fakeClient);
+  assert.equal(records.length, 0);
+});
diff --git a/delegate/review/eval/cases.ts b/delegate/review/eval/cases.ts
new file mode 100644
index 0000000..548edd0
--- /dev/null
+++ b/delegate/review/eval/cases.ts
@@ -0,0 +1,125 @@
+import { readFileSync, readdirSync, writeFileSync, mkdirSync } from "node:fs";
+import { join } from "node:path";
+import {
+  S3Client,
+  ListObjectsV2Command,
+  GetObjectCommand,
+} from "@aws-sdk/client-s3";
+import { ReviewRecordSchema } from "../schema";
+import type { ReviewRecord } from "../schema";
+
+const REVIEW_BUCKET = process.env.REVIEW_BUCKET ?? "delegate-reviews";
+
+const readBody = async (body: unknown): Promise<string> => {
+  const chunks: Buffer[] = [];
+  for await (const chunk of body as AsyncIterable<Buffer>) {
+    chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk as Uint8Array));
+  }
+  return Buffer.concat(chunks).toString("utf-8");
+};
+
+export interface LoadOptions {
+  from: string;
+  repo?: string;
+  limit?: number;
+  onlyComplete?: boolean;
+}
+
+const applyFilters = (records: ReviewRecord[], opts: LoadOptions): ReviewRecord[] => {
+  let result = records;
+  if (opts.repo) result = result.filter((r) => r.repo === opts.repo);
+  if (opts.onlyComplete) result = result.filter((r) => r.output?.status === "complete");
+  if (opts.limit !== undefined) result = result.slice(0, opts.limit);
+  return result;
+};
+
+const loadFromDir = (dir: string): ReviewRecord[] => {
+  const files = readdirSync(dir).filter((f) => f.endsWith(".json"));
+  const records: ReviewRecord[] = [];
+  for (const file of files) {
+    let parsed: unknown;
+    try {
+      parsed = JSON.parse(readFileSync(join(dir, file), "utf-8"));
+    } catch {
+      console.warn(`cases: invalid JSON in ${file}`);
+      continue;
+    }
+    const result = ReviewRecordSchema.safeParse(parsed);
+    if (!result.success) {
+      console.warn(`cases: invalid ReviewRecord in ${file}: ${result.error.message}`);
+      continue;
+    }
+    records.push(result.data);
+  }
+  return records;
+};
+
+const loadFromS3 = async (client: S3Client): Promise<ReviewRecord[]> => {
+  const keys: string[] = [];
+  let continuationToken: string | undefined;
+
+  do {
+    const res = await client.send(
+      new ListObjectsV2Command({
+        Bucket: REVIEW_BUCKET,
+        Prefix: "reviews/",
+        ContinuationToken: continuationToken,
+      }),
+    );
+    for (const obj of res.Contents ?? []) {
+      if (obj.Key && !obj.Key.endsWith("/lock")) {
+        keys.push(obj.Key);
+      }
+    }
+    continuationToken = res.NextContinuationToken;
+  } while (continuationToken);
+
+  const records: ReviewRecord[] = [];
+  for (const key of keys) {
+    let text: string;
+    try {
+      const res = await client.send(
+        new GetObjectCommand({ Bucket: REVIEW_BUCKET, Key: key }),
+      );
+      text = await readBody(res.Body);
+    } catch (err) {
+      console.warn(
+        `cases: failed to fetch ${key}: ${err instanceof Error ? err.message : String(err)}`,
+      );
+      continue;
+    }
+    let parsed: unknown;
+    try {
+      parsed = JSON.parse(text);
+    } catch {
+      console.warn(`cases: invalid JSON at ${key}`);
+      continue;
+    }
+    const result = ReviewRecordSchema.safeParse(parsed);
+    if (!result.success) {
+      console.warn(`cases: invalid ReviewRecord at ${key}: ${result.error.message}`);
+      continue;
+    }
+    records.push(result.data);
+  }
+  return records;
+};
+
+export const loadCases = async (
+  opts: LoadOptions,
+  client: S3Client = new S3Client({}),
+): Promise<ReviewRecord[]> => {
+  const records =
+    opts.from === "s3" ? await loadFromS3(client) : loadFromDir(opts.from);
+  return applyFilters(records, opts);
+};
+
+export const saveCases = (records: ReviewRecord[], dir: string): void => {
+  mkdirSync(dir, { recursive: true });
+  for (const record of records) {
+    writeFileSync(
+      join(dir, `${record.runId}.json`),
+      JSON.stringify(record, null, 2),
+    );
+  }
+};
diff --git a/delegate/review/eval/cli.ts b/delegate/review/eval/cli.ts
new file mode 100644
index 0000000..f40db30
--- /dev/null
+++ b/delegate/review/eval/cli.ts
@@ -0,0 +1,133 @@
+import { readFileSync, readdirSync, writeFileSync } from "node:fs";
+import { join } from "node:path";
+import { loadCases, saveCases } from "./cases";
+import { replayAll } from "./replay";
+import type { Result } from "./replay";
+import { createAnthropicJudgeModel, judgeAll, DEFAULT_JUDGE_MODEL } from "./judge";
+import { summarize, renderMarkdown } from "./report";
+
+const parseFlags = (args: string[]): Record<string, string | boolean> => {
+  const flags: Record<string, string | boolean> = {};
+  for (let i = 0; i < args.length; i++) {
+    const arg = args[i];
+    if (arg.startsWith("--")) {
+      const key = arg.slice(2);
+      const next = args[i + 1];
+      if (next === undefined || next.startsWith("--")) {
+        flags[key] = true;
+      } else {
+        flags[key] = next;
+        i++;
+      }
+    }
+  }
+  return flags;
+};
+
+const flag = (flags: Record<string, string | boolean>, key: string): string | undefined => {
+  const v = flags[key];
+  return typeof v === "string" ? v : undefined;
+};
+
+const boolFlag = (flags: Record<string, string | boolean>, key: string): boolean =>
+  flags[key] === true;
+
+const loadResultsFromDir = (dir: string): Result[] => {
+  const files = readdirSync(dir).filter((f) => f.endsWith(".json"));
+  return files.map((f) => JSON.parse(readFileSync(join(dir, f), "utf-8")) as Result);
+};
+
+const usage = () => {
+  console.error(
+    [
+      "Usage:",
+      "  review:eval cases snapshot --out <dir> [--repo <r>] [--limit <n>]",
+      "  review:eval replay --cases <dir|s3> --out <dir> [--variant <label>] [--concurrency 3] [--work-dir /tmp/review-eval] [--force]",
+      "  review:eval judge --cases <dir|s3> --a <dir> --b <dir> [--label-a <x>] [--label-b <y>] [--passes 4] [--model <id>] [--out <report.md>]",
+    ].join("\n"),
+  );
+  process.exit(1);
+};
+
+const main = async () => {
+  const argv = process.argv.slice(2);
+  const command = argv[0];
+
+  if (command === "cases") {
+    const subcommand = argv[1];
+    if (subcommand !== "snapshot") usage();
+    const flags = parseFlags(argv.slice(2));
+    const out = flag(flags, "out");
+    if (!out) { console.error("--out is required"); process.exit(1); }
+    const repo = flag(flags, "repo");
+    const limit = flag(flags, "limit") ? parseInt(flag(flags, "limit")!, 10) : undefined;
+
+    console.error("Loading cases from S3...");
+    const records = await loadCases({ from: "s3", repo, limit });
+    saveCases(records, out);
+    console.error(`Saved ${records.length} case(s) to ${out}`);
+    return;
+  }
+
+  if (command === "replay") {
+    const flags = parseFlags(argv.slice(1));
+    const casesFrom = flag(flags, "cases");
+    const out = flag(flags, "out");
+    if (!casesFrom || !out) { console.error("--cases and --out are required"); process.exit(1); }
+    const variant = flag(flags, "variant");
+    const concurrency = flag(flags, "concurrency") ? parseInt(flag(flags, "concurrency")!, 10) : 3;
+    const workDir = flag(flags, "work-dir") ?? "/tmp/review-eval";
+    const force = boolFlag(flags, "force");
+
+    const records = await loadCases({ from: casesFrom });
+    console.error(`Replaying ${records.length} case(s) with concurrency ${concurrency}...`);
+    const results = await replayAll(records, { out, variant, workDir, force }, { concurrency });
+    const errors = results.filter((r) => r.error);
+    console.error(
+      `Done. ${results.length - errors.length} succeeded, ${errors.length} failed.`,
+    );
+    return;
+  }
+
+  if (command === "judge") {
+    const flags = parseFlags(argv.slice(1));
+    const casesFrom = flag(flags, "cases");
+    const aDirArg = flag(flags, "a");
+    const bDirArg = flag(flags, "b");
+    if (!casesFrom || !aDirArg || !bDirArg) {
+      console.error("--cases, --a, and --b are required");
+      process.exit(1);
+    }
+    const labelA = flag(flags, "label-a") ?? "a";
+    const labelB = flag(flags, "label-b") ?? "b";
+    const passes = flag(flags, "passes") ? parseInt(flag(flags, "passes")!, 10) : 4;
+    const modelId = flag(flags, "model") ?? DEFAULT_JUDGE_MODEL;
+    const outFile = flag(flags, "out");
+
+    const records = await loadCases({ from: casesFrom });
+    const resultsA = loadResultsFromDir(aDirArg);
+    const resultsB = loadResultsFromDir(bDirArg);
+
+    console.error(`Judging ${records.length} case(s) with model ${modelId}, ${passes} passes each...`);
+
+    const model = createAnthropicJudgeModel({ model: modelId });
+    const verdicts = await judgeAll(records, resultsA, resultsB, model, passes);
+
+    const summary = summarize(verdicts);
+    const report = renderMarkdown(summary, verdicts, { labelA, labelB });
+
+    console.log(report);
+    if (outFile) {
+      writeFileSync(outFile, report);
+      console.error(`Report written to ${outFile}`);
+    }
+    return;
+  }
+
+  usage();
+};
+
+main().catch((err: unknown) => {
+  console.error(err instanceof Error ? err.message : String(err));
+  process.exit(1);
+});
