+  wallTimeMs: 60000,
+  costUsd: 0.05,
+  bundle: {
+    repo: "thegoodparty/ops",
+    prNumber: 42,
+    baseRef: "develop",
+    baseSha: "aaaaaa",
+    headSha: "bbbbbb",
+    author: "swain",
+    title: "Test PR",
+    body: "A test PR",
+    diff: "diff --git a/foo.ts b/foo.ts\n",
+    changedFiles: ["foo.ts"],
