+
+test("replayAll runs multiple cases with the worker pool", async () => {
+  const out = tmpDir();
+  const workDir = tmpDir();
+  const records = [makeRecord(), makeRecord(), makeRecord()];
+
+  let callCount = 0;
+  const countingAgent: RunAgentImpl = async () => {
+    callCount++;
