+      output: "",
+      durationMs: 10,
+      structuredOutput: { status: "complete", findings: [], summary: "ok" },
+    };
+  };
+
+  const results = await replayAll(
+    records,
+    { out, workDir, variant: "v1" },
+    { concurrency: 2 },
+    countingAgent,
+    fakeCheckout,
+  );
+
+  assert.equal(results.length, 3);
+  assert.equal(callCount, 3);
+});
